args:
# Entry points that take inputs: @name marks a function that `tomato run FILE NAME INPUTS...` starts, and each input is
# converted to its parameter's type (a number, a text, True or False). Everything after the entry name is input, as it is typed.
#   tomato run examples/args.tom                    runs main: no inputs
#   tomato run examples/args.tom prime 17           prints: 17 True
#   tomato run examples/args.tom greet bob 2 True   prints BOB twice
# A program built with `tomato build examples/args.tom -o args` takes the same words: `./args prime 17`, and `./args` for main.
# (A function that takes `*words: tuple[str]` gets every input as text; a parameter typed File gets a file opened from the input.)
from math import is_prime

@main
def main():
    print('no inputs')

@prime
def prime(n: int):
    print(n, is_prime(n))

@greet
def greet(name: str, times: uint[length=8], loud: bool):
    for i in range(times):
        if loud:
            print(name.upper())
        else:
            print(name)

compiled:
# Building a native program: `tomato build examples/compiled.tom -o compiled`, then `./compiled main 12` (a built program takes [ENTRY [INPUTS...]]: the input is main's
# parameter n; add `--mode release` to build for speed). `tomato run examples/compiled.tom main 12` runs it directly.
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

@main
def main(n: int):
    print('fib', n, '=', fib(n))
    count = 0
    for i in range(2, n + 1):
        if is_prime(i):
            count += 1
    print('primes up to', n, ':', count)
    print(n / 7, n % 7)

features:
# A tour of the core language: an error class with @init, raise and try/catch/finally, dicts and sets, loops with break
# and continue, and the math module. Run it with: tomato run examples/features.tom
from math import gcd

class NegativeError(Error):
    @init
    def make(self, message: str):
        Error.start(self, message)

def square_root_floor(n: int) -> int:
    if n < 0:
        raise NegativeError('no square root of a negative number')
    r = 0
    while (r + 1) * (r + 1) <= n:
        r += 1
    return r

@main
def main():
    words = 'the quick brown fox jumps over the lazy dog the end'.split(' ')
    counts: dict[str, int] = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    print(counts['the'], len(counts))
    seen: set[str] = {}
    for w in words:
        seen.add(w)
    print(len(seen), 'fox' in seen)
    print(gcd(84, 36), 2 ** 20)
    for n in [16, 17, -4]:
        try:
            print(n, square_root_floor(n))
        catch NegativeError as e:
            print(n, 'error:', e.message)
        finally:
            print('checked', n)
    total = 0
    for i in range(100):
        if i % 2 == 1:
            continue
        if i > 10:
            break
        total += i
    print(total)

iteration:
# Ranges and iteration: a range keeps only start, stop and step; a method marked @iter (or any function that uses yield)
# can be looped over with `for`; progress_bar (from itertools) wraps any loop that has a length.
from itertools import progress_bar  # allow: unstable (its drawing may still change, docs/provisional.md)

def fib(limit: int) -> int:
    a, b = 0, 1
    while a < limit:
        yield a
        a, b = b, a + b

class Countdown:
    start: int

    @init
    def make(self, start: int):
        self.start = start

    @iter
    def numbers(self) -> int:
        n = self.start
        while n > 0:
            yield n
            n -= 1

    @len
    def size(self) -> int:
        return self.start

@main
def main():
    r = range(5, 50, 5)
    print(r, len(r), r[1], r[-1], r[2:5], 25 in r)
    print(sum(r), list(range(3)), reversed(range(4)), range(100) == range(0, 100, 1))
    for x in fib(60):
        print(x)
    for n in Countdown(3):
        print(n)
    print(len(Countdown(7)), sum(Countdown(4)), list(Countdown(3)))
    for ch in 'abc':
        print(ch)
    for i in progress_bar(range(3), 'work'):
        print(i)

