# Heap values the compiler allocates and frees by reference counting (D36a).
# tomato build examples/objects.tom -o objects && ./objects main 5
class Item:
    name: str
    qty: int

    @init
    def make(self, name: str, qty: int):
        self.name = name
        self.qty = qty

class Inventory:
    items: list[Item] = []

    def add(self, name: str, qty: int):
        self.items.append(Item(name, qty))

    def total(self) -> int:
        return sum([item.qty for item in self.items])

    def describe(self) -> str:
        return ''.join([f'{item.name}x{item.qty} ' for item in self.items])

@main
def main(n: int):
    inv = Inventory()
    for i in range(n):
        inv.add(f'item{i}', i * 2)
    print(inv.describe())
    print('total', inv.total(), 'chars', len(inv.describe()))

shapes:
# Interfaces and classes: an interface that extends another, a class that implements it with private fields, and a
# subclass that overrides a method; describe() takes any Shape. Run it with: tomato run examples/shapes.tom
interface Named:
    def name(self) -> str

interface Shape(Named):
    def area(self) -> int

class Rect implements Shape:
    private w: int
    private h: int

    @init
    def start(self, w: int, h: int):
        self.w = w
        self.h = h

    def name(self) -> str:
        return "rect"

    def area(self) -> int:
        return self.w * self.h

class Square(Rect):
    @init
    def make(self, s: int):
        Rect.start(self, s, s)

    override def name(self) -> str:
        return "square"

def describe(s: Shape) -> int:
    print(s.name())
    return s.area()

@main
def main():
    print(describe(Rect(2, 3)))
    print(describe(Square(4)))
